        $action=$_POST['action']??'';
        if($action==='upload'){$job=legacy_http_upload($koneksi,$_POST,$_FILES);header('Location: legacy_import.php?id='.$job['id'].'&step=review');exit;}
        if(!in_array($action,['confirm','cancel'],true))throw new DomainException('Tindakan tidak tersedia.',400);
        $job=legacy_http_decide($koneksi,$action,$_POST);header('Location: legacy_import.php?id='.$job['id'].'&step=result');exit;
    }
    $health=legacy_readiness($koneksi);
    if($job){$rows=legacy_http_rows($id,$_GET);$preview=in_array($job['state'],['ready','imported'],true)?legacy_preview($id):null;if(!isset($_GET['step']))$step=$job['state']==='imported'?'result':'review';}
}catch(Throwable $e){http_response_code($e instanceof DomainException&&in_array($e->getCode(),[400,403,404,503],true)?$e->getCode():409);$error=$e instanceof DomainException?$e->getMessage():'Permintaan gagal. Muat ulang status sebelum mencoba kembali.';}
